using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly string baseUrl;
    private readonly HttpClient client;
    private int status = 200;
    private string responseBody = "{\"status\":\"approved\"}";
    private string? method, path, contentType, requestBody;

    public HttpPaymentGatewayTests()
    {
        int port;
        using (var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0))
        {
            probe.Start();
            port = ((IPEndPoint)probe.LocalEndpoint).Port;
        }
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch { return; }

            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            requestBody = await reader.ReadToEndAsync();
            method = ctx.Request.HttpMethod;
            path = ctx.Request.Url!.AbsolutePath;
            contentType = ctx.Request.ContentType;

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            ctx.Response.ContentLength64 = bytes.Length;
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize();

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var doc = JsonDocument.Parse(requestBody!);
        var root = doc.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal(JsonValueKind.Number, root.GetProperty("amount").ValueKind);
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_declined()
    {
        responseBody = "{\"status\":\"declined\"}";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        responseBody = "{\"id\":\"a1\",\"status\":\"approved\",\"risk\":{\"score\":3}}";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_declined_whatever_the_body()
    {
        status = 402;
        responseBody = "{\"error\":\"card_refused\"}";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_are_failures_not_declines(int code)
    {
        status = code;
        responseBody = "{\"error\":\"nope\"}";
        var ex = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)code, ex.StatusCode);
    }

    [Theory]
    [InlineData("{}")]
    [InlineData("{\"status\":null}")]
    [InlineData("{\"status\":\"pending\"}")]
    [InlineData("{\"status\":\"APPROVED\"}")]
    [InlineData("null")]
    public async Task An_unrecognised_answer_is_never_treated_as_approved(string body)
    {
        responseBody = body;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    [InlineData("{\"status\":{\"value\":\"approved\"}}")]
    public async Task A_malformed_answer_fails_loudly(string body)
    {
        responseBody = body;
        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
